#include <Arduino.h>

int Pin = 2;

void setup() {
    Serial.begin(115200);
    pinMode(Pin, OUTPUT);
}

void loop() {
    if (Serial.available() > 0) {
        char command = Serial.read();

        if (command == 'F') {
            digitalWrite(Pin, HIGH);
            Serial.println("F received!");
        } else {
            digitalWrite(Pin, LOW);
        }
    }
}
